import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.C66fElYV.js";const h=JSON.parse('{"title":"迁移步骤与分期路线（ai）","description":"","frontmatter":{},"headers":[],"relativePath":"arch/ai/07-migration-plan.md","filePath":"arch/ai/07-migration-plan.md","lastUpdated":1791676775000}'),r={name:"arch/ai/07-migration-plan.md"};function i(n,e,l,c,s,p){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="迁移步骤与分期路线-ai" tabindex="-1">迁移步骤与分期路线（ai） <a class="header-anchor" href="#迁移步骤与分期路线-ai" aria-label="Permalink to &quot;迁移步骤与分期路线（ai）&quot;">​</a></h1><blockquote><p>本文是「Solon-AI 迁移到 Go」系列的第八篇（TDD 路线图与分期）。 前置：<a href="./00-overview.html"><code>00-overview.md</code></a>（范围与决策索引）、各设计篇（02–06）。 本文是<strong>执行契约</strong>：每期的交付物、测试用例清单、验收标准（Definition of Done）。供逐卡执行与进度核对；顺序可按审核意见调整（§3 的 P3/P4 即设计为可对调）。</p></blockquote><hr><h2 id="_0-tdd-思想如何贯穿本迁移" tabindex="-1">0. TDD 思想如何贯穿本迁移 <a class="header-anchor" href="#_0-tdd-思想如何贯穿本迁移" aria-label="Permalink to &quot;0. TDD 思想如何贯穿本迁移&quot;">​</a></h2><ol><li><strong>测试先行于方言</strong>：每个方言的请求 JSON / 响应 SSE 片段，先从 Java 侧测试资源（<code>solon-ai</code> 聚合模块的 <code>features/ai/*</code>）搬译成 Go 的 httptest 假服务回放用例——<strong>不依赖真实厂商</strong>，语义对照以 Java 行为为黄金样本。</li><li><strong>不变量即测试</strong>：流式 6 条不变量（01 §2.1）、copy-before-mutate（03 §5.2）、MCP 帧判别表（04 §10.1）这类「契约级」行为逐条固化为命名测试。</li><li><strong>黑盒与自包含</strong>：全部测试走 <code>_test/&lt;area&gt;_test</code> 外部测试包 + 嵌入式依赖（httptest、in-process 回环、sqlite），与仓库测试约定一致；真实厂商/真实向量库联调用环境变量开关（对照 <code>FLOW_MYSQL_DSN</code> 先例），默认跳过。</li><li><strong>每期收口跑全量</strong>：分期验收 = <code>go test</code> 全绿 + CLAUDE.md 模块表/go.work 同步更新。</li></ol><hr><h2 id="_1-测试模块布局-遵循-aifei-go-约定" tabindex="-1">1. 测试模块布局（遵循 aifei-go 约定） <a class="header-anchor" href="#_1-测试模块布局-遵循-aifei-go-约定" aria-label="Permalink to &quot;1. 测试模块布局（遵循 aifei-go 约定）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>覆盖</th><th>嵌入依赖</th></tr></thead><tbody><tr><td><code>_test/ai_test</code></td><td><code>./ai</code>：消息/事件/工具/schema/方言（假服务回放）/流式不变量/会话/router/embedding/rag SPI/talent/ui-aisdk</td><td>httptest（标准库）</td></tr><tr><td><code>_test/mcp_test</code></td><td><code>./mcp</code>：帧判别/会话/三传输回环/桥</td><td>httptest + 自身二进制 stdio 回环</td></tr><tr><td><code>_test/ai_agent_test</code></td><td><code>./ai/agent</code> + <code>./ai/flow</code>：Simple/ReAct/Team、协议拓扑、HITL 挂起恢复、YAML 组件链</td><td>假 ChatModel（stub dialect）</td></tr><tr><td><code>_test/ai_plugin_test</code></td><td><code>./plugins/ai</code> 系列：装配、ragloader/ragrepo 后端</td><td>sqlite（db）+ 可选真连开关</td></tr></tbody></table><p>共享夹具：<code>stubmodel</code>（假方言：脚本化事件序列，模拟文本/工具调用/思考交错）放 <code>_test/ai_test/internal/stubmodel</code>，<code>ai_agent_test</code> 以 replace 引用同源副本或直接复制小份（仓库无跨测试模块共享惯例，倾向复制并注明来源）。</p><p>各模块 go.mod 依 C1/C3 惯例：module <code>…/_test/&lt;area&gt;_test</code>、显式 require 被测模块、相对 replace、登记 <code>go.work</code>。</p><hr><h2 id="_2-分期总览" tabindex="-1">2. 分期总览 <a class="header-anchor" href="#_2-分期总览" aria-label="Permalink to &quot;2. 分期总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>期</th><th>主题</th><th>新增模块</th><th>预估行数（含测试）</th></tr></thead><tbody><tr><td><strong>P0</strong></td><td>聊天核心（call 路径）</td><td><code>./ai</code></td><td>2,200–2,800</td></tr><tr><td><strong>P1</strong></td><td>流式 + 方言矩阵 + 周边</td><td><code>./ai</code>（续）</td><td>2,500–3,200</td></tr><tr><td><strong>P2</strong></td><td>智能体 + AI 流编排</td><td><code>./ai/agent</code>、<code>./ai/flow</code>（+flow 一处增量）</td><td>2,300–3,000</td></tr><tr><td><strong>P3</strong></td><td>MCP 协议与双端</td><td><code>./mcp</code>（+ <code>ai/mcp</code> 桥）</td><td>2,000–2,600</td></tr><tr><td><strong>P4</strong></td><td>RAG + 配置装配 + ui 收尾</td><td><code>./ai/rag</code>（续）、<code>./plugins/ai</code></td><td>1,200–1,600</td></tr><tr><td><strong>P5</strong></td><td>按需解锁</td><td>ragloader/ragrepo/talents/sandbox/harness/loop/agui/ACP</td><td>视范围</td></tr></tbody></table><p>依赖链：P0→P1→P2 严格顺序；<strong>P3 与 P4 可并行、可与 P2 后半互换</strong>（MCP 与 RAG 互不依赖，都只依赖 P1 的 <code>./ai</code>）。P5 各项彼此独立。</p><hr><h2 id="_3-p0-聊天核心-call-路径" tabindex="-1">3. P0：聊天核心（call 路径） <a class="header-anchor" href="#_3-p0-聊天核心-call-路径" aria-label="Permalink to &quot;3. P0：聊天核心（call 路径）&quot;">​</a></h2><h3 id="p0-a-消息与内容块" tabindex="-1">P0-a 消息与内容块 <a class="header-anchor" href="#p0-a-消息与内容块" aria-label="Permalink to &quot;P0-a 消息与内容块&quot;">​</a></h3><ul><li>交付：<code>ai/message.go</code>、<code>ai/content.go</code>（02 §2 全契约）；<code>ai.Prompt</code>。</li><li>测试：四角色工厂；多模态 Content 序列化判别（type 分发往返）；<code>OfUserAugment</code>；<code>Clone</code> 深拷贝断言；大 base64 降级占位（&gt;64KiB）。</li><li>验收：表驱动往返 <code>Marshal→Unmarshal→相等</code> 全绿。</li></ul><h3 id="p0-b-事件模型与聚合器" tabindex="-1">P0-b 事件模型与聚合器 <a class="header-anchor" href="#p0-b-事件模型与聚合器" aria-label="Permalink to &quot;P0-b 事件模型与聚合器&quot;">​</a></h3><ul><li>交付：<code>event.go</code>（30 常量一次定义齐 + Group/IsDelta）、<code>accumulator.go</code>。</li><li>测试：构造事件序列（手写）→ 聚合出 AssistantMessage/Usage/finishReason；工具调用 delta 拼接（args 增量合并）；thinking 与 text 并存；<code>BuildResponse</code> 快照完整性。</li><li>验收：聚合器对「无事件流」「仅 ERROR」的边界行为符合不变量 1/3。</li></ul><h3 id="p0-c-工具家族与-schema-生成" tabindex="-1">P0-c 工具家族与 schema 生成 <a class="header-anchor" href="#p0-c-工具家族与-schema-生成" aria-label="Permalink to &quot;P0-c 工具家族与 schema 生成&quot;">​</a></h3><ul><li>交付：<code>tool.go</code>、<code>tool_schema.go</code>、<code>tool_reflect.go</code>。</li><li>测试：<code>NewTool</code> 链式构建 → InputSchema 生成（基础类型/嵌套/slice/map/time/enum）；<code>RegisterTools</code> 反射绑定（方法名 kebab 化、param tag 解析、默认值、三种返回形态）；<code>Call</code> 的 panic→recover→<code>ToolResultErr</code>。</li><li>验收：<code>_OrderTools</code> 样例（Java 测试同名类搬译）schema 与 Java 输出逐字段一致。</li></ul><h3 id="p0-d-httpx-与-openai-方言-call" tabindex="-1">P0-d httpx 与 openai 方言（call） <a class="header-anchor" href="#p0-d-httpx-与-openai-方言-call" aria-label="Permalink to &quot;P0-d httpx 与 openai 方言（call）&quot;">​</a></h3><ul><li>交付：<code>httpx</code>（Client/PostJSON/SSE 解析器）、<code>dialect.go</code> SPI、<code>ai/dialect/openai</code>（BuildRequestJSON + ParseResponseJSON 的 call 分支）。</li><li>测试：SSE 解析器独立单测（分帧/多行 data/事件名/[DONE]/超大行/CRLF/注释行）；httptest 假 OpenAI 回放固定 JSON（含 usage/tool_calls/finish_reason 各形态）→ 事件序列断言。</li><li>验收：<strong>不真连</strong>任何厂商；假服务覆盖 ≥ Java <code>features/ai/openai</code> 用例集。</li></ul><h3 id="p0-e-模型执行管线-call-autotoolcall" tabindex="-1">P0-e 模型执行管线（call + autoToolCall） <a class="header-anchor" href="#p0-e-模型执行管线-call-autotoolcall" aria-label="Permalink to &quot;P0-e 模型执行管线（call + autoToolCall）&quot;">​</a></h3><ul><li>交付：<code>model.go</code>（Config/ChatModel/RequestDesc/Response）、<code>options.go</code>、<code>usage.go</code>、<code>session.go</code>（Memory）、<code>interceptor.go</code>。</li><li>测试：系统提示组装序（role+instruction+schema 指令+talent 指令）；autoToolCall 递归（假工具 + 假模型两轮）消息表追加正确（assistant(tool_calls)→tool）；<code>Response.Events()</code> 全轨迹；maxTurns 不在此层（agent 层职责）。</li><li>验收：<code>go test ./_test/ai_test</code> 全绿；<code>go.work</code>/CLAUDE.md 登记 <code>./ai</code> 与 <code>_test/ai_test</code>。</li></ul><hr><h2 id="_4-p1-流式与方言矩阵" tabindex="-1">4. P1：流式与方言矩阵 <a class="header-anchor" href="#_4-p1-流式与方言矩阵" aria-label="Permalink to &quot;4. P1：流式与方言矩阵&quot;">​</a></h2><h3 id="p1-a-stream-主路径" tabindex="-1">P1-a stream 主路径 <a class="header-anchor" href="#p1-a-stream-主路径" aria-label="Permalink to &quot;P1-a stream 主路径&quot;">​</a></h3><ul><li>交付：<code>RequestDesc.Stream/StreamChan/CallStream</code>、<code>stream_context.go</code>。</li><li>测试：不变量 1–5 逐条命名测试；消费方 sink 出错即中止（无 ERROR 事件、透传错误）；ctx cancel 在帧间隙生效；工具递归子流事件在同管线续播且 Step 递增；channel 形态背压（慢消费者不丢事件）。</li><li>验收：openai 假 SSE（chunked）全链路绿。</li></ul><h3 id="p1-b-方言矩阵" tabindex="-1">P1-b 方言矩阵 <a class="header-anchor" href="#p1-b-方言矩阵" aria-label="Permalink to &quot;P1-b 方言矩阵&quot;">​</a></h3><ul><li>交付：<code>anthropic</code>（签名/thinking/input_json_delta/cache 计量）、<code>gemini</code>（thought/candidate）、<code>ollama</code>、<code>dashscope</code>；openai-responses 后置到 P1 末。</li><li>测试：每方言 ≥ 3 组回放（纯文本流 / 工具流 / 多 choice 或 candidate 归一）；请求 JSON 快照比对（Java 侧 dump 为黄金样本）。</li><li>验收：<code>SelectDialect</code> 优先级表驱动（standard &gt; provider &gt; openai 补位）。</li></ul><h3 id="p1-c-embedding-拦截器-router" tabindex="-1">P1-c embedding + 拦截器 + router <a class="header-anchor" href="#p1-c-embedding-拦截器-router" aria-label="Permalink to &quot;P1-c embedding + 拦截器 + router&quot;">​</a></h3><ul><li>交付：<code>ai/embedding</code>（+openai/ollama/dashscope 三方言）、<code>interceptor.go</code> 链、<code>ai/router</code>（RoundRobin/加权/规则/Smart 四策略）。</li><li>测试：embed 批量与维度；拦截器 onPrepare 改写系统提示、InterceptCall 包裹链序；router 显式 attr 路由 &gt; 策略选择；加权分布（统计断言）。</li><li>验收：Smart 路由（LLM 决策）用假模型测。</li></ul><h3 id="p1-d-会话扩展-ui-aisdk" tabindex="-1">P1-d 会话扩展 + ui/aisdk <a class="header-anchor" href="#p1-d-会话扩展-ui-aisdk" aria-label="Permalink to &quot;P1-d 会话扩展 + ui/aisdk&quot;">​</a></h3><ul><li>交付：<code>FileSession</code>（原子写）、<code>ai/ui/aisdk</code>（WriteStream/WrapResponse + 19 parts）。</li><li>测试：会话窗口截断/RemoveLatest；aisdk 事件→parts 映射表驱动；httptest 完整 SSE 输出比对。</li><li>验收：一个端到端 demo（httptest 假模型 + aisdk 输出）入 <code>_test/ai_test</code> 示例目录。</li></ul><hr><h2 id="_5-p2-智能体与-ai-流编排" tabindex="-1">5. P2：智能体与 AI 流编排 <a class="header-anchor" href="#_5-p2-智能体与-ai-流编排" aria-label="Permalink to &quot;5. P2：智能体与 AI 流编排&quot;">​</a></h2><h3 id="p2-a-simple-基座" tabindex="-1">P2-a Simple + 基座 <a class="header-anchor" href="#p2-a-simple-基座" aria-label="Permalink to &quot;P2-a Simple + 基座&quot;">​</a></h3><ul><li>交付：<code>ai/agent</code> 模块（AgentBase/Session/Event/Trace/Metrics）+ <code>simple/</code>。</li><li>测试：Agent 放进 flow 图当节点（<code>AddActivityNamed</code>）端到端；<code>_SESSION_</code> 装载复用；retry 仅传输错误重试；<code>OutputKey</code> 写回 ctx；流式 SimpleDelta 转发 + 终态聚合。</li><li>验收：<code>go.work</code> 登记 <code>./ai/agent</code>、<code>_test/ai_agent_test</code>。</li></ul><h3 id="p2-b-react" tabindex="-1">P2-b ReAct <a class="header-anchor" href="#p2-b-react" aria-label="Permalink to &quot;P2-b ReAct&quot;">​</a></h3><ul><li>交付：<code>react/</code>（两 Task + options）+ StopLoop/ToolRetry 拦截器。</li><li>测试：reason→action→reason 两轮收敛（stubmodel 脚本）；maxTurns 保险丝文案；autoRethink 放宽；会话窗口；死循环指纹检测；工具失败重试次数。</li><li>验收：Java <code>ReActStreamTest</code> 场景搬译（事件序列断言 Reason*/ToolCall*/RunEnd）。</li></ul><h3 id="p2-c-team-协议" tabindex="-1">P2-c Team + 协议 <a class="header-anchor" href="#p2-c-team-协议" aria-label="Permalink to &quot;P2-c Team + 协议&quot;">​</a></h3><ul><li>交付：<code>team/</code>（引擎接线 + ProtocolBase）+ Sequential → Hierarchical → Swarm 三协议（其余 5 个随后增量）；<strong>flow 增量 D8</strong>（已定稿方案 A：<code>Node.Attachment/SetAttachment</code>，向后兼容 + flow 全量回归，单独成提交）。</li><li>测试：Sequential 静态拓扑（零 LLM 决策）；Hierarchical 的 supervisor 路由（假模型回 agent 名 → 边 when 命中）；<code>PrepareAgentPrompt</code> copy-before-mutate 专项（跨 agent 不串写）；拦截器经 <code>engine.AddInterceptor</code> 生效；会话挂起（Pending→图 Stop→快照→恢复续跑）。</li><li>验收：<code>flow</code> 模块现有测试全绿（增量无回归）；8 协议至少 3 个绿。</li></ul><h3 id="p2-d-ai-flow-组件" tabindex="-1">P2-d ai/flow 组件 <a class="header-anchor" href="#p2-d-ai-flow-组件" aria-label="Permalink to &quot;P2-d ai/flow 组件&quot;">​</a></h3><ul><li>交付：<code>ai/flow</code> 模块（12 组件 + <code>RegisterDefaults</code> + attrs 常量表）。</li><li>测试：<code>chat_case1.chain.yml</code> <strong>逐字</strong>搬译执行（VarInput→VarCopy→ChatModelCom→ConsoleOutput）；stream:true 时输出事件流句柄；chatConfig 从 meta 构建 + 附件缓存命中（第二次执行不重建，D8 验证）；节点事件 <code>flow.node.start/end</code> 经 <code>ctx.EventBus()</code> 可订阅；exclusive 网关 + enjoy 条件（react1.yml 场景）。</li><li>验收：YAML 与 solon-ai-flow 测试资源兼容（同 schema 无改动可跑）。</li></ul><hr><h2 id="_6-p3-mcp" tabindex="-1">6. P3：MCP <a class="header-anchor" href="#_6-p3-mcp" aria-label="Permalink to &quot;6. P3：MCP&quot;">​</a></h2><h3 id="p3-a-协议层" tabindex="-1">P3-a 协议层 <a class="header-anchor" href="#p3-a-协议层" aria-label="Permalink to &quot;P3-a 协议层&quot;">​</a></h3><ul><li>交付：<code>schema.go/types.go/version.go/session.go</code>（<code>./mcp</code> 模块）。</li><li>测试：<code>UnmarshalMessage</code> 判别表驱动（含畸形 id 拒绝）；pending 表并道（并发 50 请求乱序回包）；版本协商矩阵。</li><li>验收：<code>_test/mcp_test</code> 建立；零外部依赖（go.mod 只 require 内部 json/log）。</li></ul><h3 id="p3-b-客户端" tabindex="-1">P3-b 客户端 <a class="header-anchor" href="#p3-b-客户端" aria-label="Permalink to &quot;P3-b 客户端&quot;">​</a></h3><ul><li>交付：stdio 传输 + <code>Client</code> 门面 + 心跳重连。</li><li>测试：自二进制 stdio 回环（initialize→list→call→ping→变更通知）；超时与重连退避（假延迟注入）。</li><li>验收：<code>ai/mcp</code> 桥（Provider.Tools 映射 + CallTool 透传 + IsError 前缀 + 允许/拒绝清单 + 游标缓存）接入假函数调用循环绿。</li></ul><h3 id="p3-c-服务端" tabindex="-1">P3-c 服务端 <a class="header-anchor" href="#p3-c-服务端" aria-label="Permalink to &quot;P3-c 服务端&quot;">​</a></h3><ul><li>交付：<code>Server</code> 门面 + <code>Handler()</code>（streamable HTTP 全语义）+ <code>RunStdio</code> + 旧式 SSE 兼容 + 安全钩子。</li><li>测试：httptest 回环全流程（会话建立/工具注册注销变更/资源订阅更新/提示/DELETE 注销/会话失效重连/Last-Event-ID）；<code>aifei</code> 挂载（<code>WithHTTPHandler</code> 裸通道）互操作（mcp 客户端 ↔ aifei 服务端）。</li><li>验收：对标准 MCP 客户端脚本（若可得）冒烟；P3 整体收口更新 CLAUDE.md。</li></ul><hr><h2 id="_7-p4-rag-与装配-可与-p3-并行" tabindex="-1">7. P4：RAG 与装配（可与 P3 并行） <a class="header-anchor" href="#_7-p4-rag-与装配-可与-p3-并行" aria-label="Permalink to &quot;7. P4：RAG 与装配（可与 P3 并行）&quot;">​</a></h2><h3 id="p4-a-spi-与内置实现" tabindex="-1">P4-a SPI 与内置实现 <a class="header-anchor" href="#p4-a-spi-与内置实现" aria-label="Permalink to &quot;P4-a SPI 与内置实现&quot;">​</a></h3><ul><li>交付：<code>ai/rag</code>（Document/Loader/Splitter/Repository/Storer/Lifecycle/Query + TextLoader + InMemory + 相似度工具）。</li><li>测试：全参数矩阵（limit/阈值/新鲜度/过滤/禁重滤）；enjoy 过滤表达式表驱动（SnEL 迁移表逐条）。</li></ul><h3 id="p4-b-切分器与检索工具" tabindex="-1">P4-b 切分器与检索工具 <a class="header-anchor" href="#p4-b-切分器与检索工具" aria-label="Permalink to &quot;P4-b 切分器与检索工具&quot;">​</a></h3><ul><li>交付：4 切分器 + Pipeline；<code>PromptAugment</code>、<code>RepositoryTool</code>（rerank 接口位）。</li><li>测试：TokenSize 近似计数（注入假 Tokenizer 对照）；SemanticSplitter 假 embedding 切点；RepositoryTool 在假 agent 循环中被选中并回注结果。</li></ul><h3 id="p4-c-搜索即仓储" tabindex="-1">P4-c 搜索即仓储 <a class="header-anchor" href="#p4-c-搜索即仓储" aria-label="Permalink to &quot;P4-c 搜索即仓储&quot;">​</a></h3><ul><li>交付：<code>rag/search</code>（tavily/bocha/baidu；APIKey 经环境变量）。</li><li>测试：httptest 假回放（三家响应形状）；<code>Repository</code> 只读断言（不可断言为 Storer）。</li></ul><h3 id="p4-d-配置装配-plugins-ai" tabindex="-1">P4-d 配置装配（plugins/ai） <a class="header-anchor" href="#p4-d-配置装配-plugins-ai" aria-label="Permalink to &quot;P4-d 配置装配（plugins/ai）&quot;">​</a></h3><ul><li>交付：<code>./plugins/ai</code>：读 <code>ai.*</code>（模型注册表/默认模型/embedding/agent 段/mcp 客户端段/可选 server 段）→ 包级默认（<code>ai.Use(name)</code> 语义经 registry 提供）。</li><li>测试：<code>app.yml</code> 样例装配出可用 ChatModel（stub doer）；缺省/多模型/环境变量覆盖（对照 storage/kafka 插件测试式样）。</li><li>验收：<code>_test/ai_plugin_test</code> 建立；demo 场景（config 驱动的一问一答）跑通。</li></ul><hr><h2 id="_8-p5-按需解锁-每项独立立项" tabindex="-1">8. P5：按需解锁（每项独立立项） <a class="header-anchor" href="#_8-p5-按需解锁-每项独立立项" aria-label="Permalink to &quot;8. P5：按需解锁（每项独立立项）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>触发建议</th><th>首卡</th></tr></thead><tbody><tr><td>ragloader（markdown/html/ddl）</td><td>RAG 真实语料接入时</td><td>markdown 标题切分 loader</td></tr><tr><td>ragrepo（es/pgvector）</td><td>向量库选型定时</td><td>ES 后端（复用 plugins/elasticsearch，knn 查询）</td></tr><tr><td>talents 五件套</td><td>编码/系统代理场景</td><td>file talent 竖切</td></tr><tr><td>sandbox</td><td>cli talent 或独立安全需求</td><td>darwin Seatbelt 后端</td></tr><tr><td>harness / loop</td><td>talents+sandbox 就绪后</td><td>AgentDefinition frontmatter 解析</td></tr><tr><td>agui / 其余方言扩展 / ACP</td><td>前端协议或编辑器需求</td><td>agui 事件族</td></tr></tbody></table><p>每项立项时在本篇追加小节（对照 flow 系列的 <code>06-mysql-repository.md</code> 追加式收尾）。</p><h3 id="p5-t-talents-五件套-2026-10-10-立项-用户解锁-契约-06-talents-and-extended-md-§1-§2" tabindex="-1">P5-T talents 五件套（2026-10-10 立项，用户解锁；契约 <code>06-talents-and-extended.md</code> §1/§2） <a class="header-anchor" href="#p5-t-talents-五件套-2026-10-10-立项-用户解锁-契约-06-talents-and-extended-md-§1-§2" aria-label="Permalink to &quot;P5-T talents 五件套（2026-10-10 立项，用户解锁；契约 `06-talents-and-extended.md` §1/§2）&quot;">​</a></h3><p>依赖：P0/P1 已落地的 Talent SPI（<code>ai/talent.go</code>：接口 7 方法 + <code>TalentBase</code> + <code>ActiveTalents</code> 管线接线 + wikiTalent 竖切测试）。落位：file/sys/diff/web 基础面 → <code>./ai</code> 子包 <code>ai/talent/&lt;name&gt;</code>（零新增依赖；web 走 <code>ai/httpx</code> + <code>ai/rag/search</code>）；text2sql → <code>./plugins/ai/talent/text2sql</code>（带 <code>./db</code> 依赖，按 06 §2 落位规则出 ai 模块）。测试：前四件入 <code>_test/ai_test</code>（<code>talent_&lt;name&gt;_test.go</code>），text2sql 入 <code>_test/ai_plugin_test</code>。</p><ul><li><strong>P5-t1 file</strong>：读/写/zip 工具（ReadFile/WriteFile/Zip/Unzip）+ 路径边界校验（根目录逃逸防护）；兼作 SPI 全链路竖切验证（准入/指令块/工具 <code>talent</code> meta 染色端到端）。</li><li><strong>P5-t2 sys</strong>：Shell/Python/Nodejs 执行工具（<code>os/exec</code> 的 ProcessExecutor 等价物：超时/输出捕获/exit code 语义）+ SystemClock。</li><li><strong>P5-t3 diff</strong>：apply-diff/apply-patch 工具（diff 语法解析，纯字符串处理）。</li><li><strong>P5-t4 web（基础面）</strong>：Webfetch（httpx 拉页抽正文）+ Websearch（走 rag/search 三家）；crawler/flexmark 转 md 留 P5 后期。</li><li><strong>P5-t5 text2sql</strong>：方言感知的 SQL 生成工具；复用 <code>db/dialect</code> 与 <code>db.Table</code> 表元数据注册表。</li></ul><p>验收：五件各自黑盒测试全绿（TempDir 假文件系统、真 exec 安全命令、httptest 假回放）；<code>ChatOptions.Talents</code> 挂入后指令块 + 工具部署端到端断言；CLAUDE.md 模块表/架构段同步；收口随下一舰队发版。</p><h3 id="p5-s-sandbox-2026-10-10-立项-用户解锁-契约-06-talents-and-extended-md-§3" tabindex="-1">P5-S sandbox（2026-10-10 立项，用户解锁；契约 <code>06-talents-and-extended.md</code> §3） <a class="header-anchor" href="#p5-s-sandbox-2026-10-10-立项-用户解锁-契约-06-talents-and-extended-md-§3" aria-label="Permalink to &quot;P5-S sandbox（2026-10-10 立项，用户解锁；契约 `06-talents-and-extended.md` §3）&quot;">​</a></h3><p>依赖：仅内部 <code>log</code>，零外部依赖。落位 <code>./sandbox</code> 新模块（cli/code/memory talents 与 harness/loop 的前置，06 §9 依赖链）。Java 源 <code>solon-ai-sandbox</code>（Claude Code sandbox-runtime 的 Java 移植，6.4K 行）；Go 移植按平台分卡，Manager 实例化（非 Java 静态单例——06 契约决策，便于测试与多配置）。</p><ul><li><strong>P5-s1 darwin Seatbelt（首卡）</strong>：配置层全家（RuntimeConfig/Network/Filesystem/Seccomp/Ripgrep/Windows 结构位）+ 读写限制结构（读=deny-then-allow-back、写=allow-only）+ 平台探测与依赖检查 + macOS Seatbelt profile 生成（move-blocking 防绕过/符号链接边界防护/强制拒绝清单：shell 启动文件与 .git）+ Manager 门面（WrapWithSandbox/Argv、UpdateConfig 热更新、CleanupAfterCommand、违规存储）+ 域名过滤（DomainPatternMatcher/HostUtils/NetworkFilter，fail-closed：无配置/畸形主机/回调异常一律拒绝）+ 工具层（glob→regex、路径规范化 <code>~</code>/相对路径/符号链接、shell 引用、代理环境变量注入）。测试 <code>_test/sandbox_test</code>（黑盒；真 <code>sandbox-exec</code> 读写拒绝/放行回环）。</li><li><strong>P5-s2 linux bwrap</strong>：<code>bwrap.go</code>（外层 bwrap <code>--unshare-net</code>/文件系统 bind/tmpfs 限制/<code>--unshare-pid</code>+<code>--proc</code> + 内层 socat 3128/1080 监听回连桥 socket、apply-seccomp 两段式 unix socket 封锁 + 宿主侧 socat 桥 <code>InitializeLinuxNetworkBridge</code> + mount 点计数延迟清理 + 强制拒绝清单 rg 扫描 + 写 glob 过滤/读 glob 展开语义）。</li><li><strong>P5-s3 代理服务器</strong>：HTTP CONNECT 正向代理 + SOCKS5 + ParentProxyResolver + TLS 终止/mitm（首卡仅预留 NetworkConfig 结构位与 SetProxyPorts 注入口）。</li><li><strong>P5-s4 windows</strong>：WFP 后端（srt-win.exe CLI 薄包装：二进制定位/组与 WFP 状态/一次性安装/包装 spawn 描述/就绪检查）。</li></ul><p>验收（首卡）：profile 生成黄金断言（读写规则次序/网络限制分支/pty/apple events/弱隔离开关）+ 真 sandbox-exec 回环（allowOnly 外写失败、denyRead 读失败、放行路径成功、无限制命令原样返回）+ 过滤矩阵与 glob/路径规范化表驱动；CLAUDE.md 模块表/测试矩阵同步。</p><p><strong>P5-s1 已落地（2026-10-10）</strong>：<code>./sandbox</code> 模块 12 文件（platform/config/restriction/glob/path/shell/net/violation/sandbox/backend_darwin + linux/windows 结构位占位）+ <code>_test/sandbox_test</code> 黑盒 19 用例全绿（含真 sandbox-exec 回环）。与 Java 的三处对齐勘误（移植期修正）：glob 静态基目录先剥尾 <code>/</code> 再 canonicalize（否则基目录与 glob 段间的分隔符在符号链接解析后丢失——Java substring 语义照抄后以测试暴露）；<code>isValidHost</code> 是宽松 DNS-label 字符集门（<code>1.2.3.4.5</code> 过门，严格拒收在 <code>CanonicalizeHost</code>）；<code>removeTrailingGlobSuffix</code> 裸 <code>**</code> 原样返回（仅剥 <code>/**</code> 尾）。真机探针结论留档：读拒绝=进程 SIGABRT（exit 134），写拒绝=EPERM 报错返回——两类都可用 <code>err != nil</code> 断言。</p><p><strong>P5-s2 已落地（2026-10-10）</strong>：<code>bwrap.go</code>（对标 <code>LinuxSandboxBackend.java</code> 1483 行逐函数移植）+ <code>sandbox.go</code> 接线（<code>wrapLinux</code>/<code>ensureLinuxBridge</code>/<code>buildWriteConfig</code> 平台分支）+ <code>_test/sandbox_test/bwrap_test.go</code> 黑盒 15 用例全绿。移植期发现与偏差（均已在代码注释注明）：</p><ul><li><strong>隐式 GOOS 构建约束陷阱（s1 遗留隐患，本次修复）</strong>：<code>backend_linux.go</code>/<code>backend_windows.go</code> 文件名后缀使它们被其他平台的构建剔除——<code>GOOS=linux go build</code> 自 s1 起就坏（darwin 上看不见重复声明、linux 上缺 darwin 符号）。后端文件改名 <code>seatbelt.go</code>/<code>bwrap.go</code>（argv/profile 生成是纯字符串操作，全平台编译可测；真 sandbox-exec/bwrap 执行自然只在对应平台有意义）。</li><li><strong>socat 桥懒建（有意偏离）</strong>：Java 仅在 <code>initialize()</code> 且当时端口已设置才建桥——实际流程端口总是后到（代理服务器 P5-s3 启动后回填），桥永远建不起来；Go 在 Manager 首次受限包装时按需建桥（<code>ensureLinuxBridge</code>），失败非致命（网络走无桥全拒分支）。</li><li><strong>读 glob 怪癖忠实保留</strong>：Java <code>wrapWithSandbox</code> 的 <code>buildReadConfig</code> 不展开读 glob，bwrap 侧按不存在路径静默跳过；<code>getFsReadConfig</code> 是另一条展开路径 → Go 导出 <code>LinuxExpandReadPaths</code> 作对应物，wrap 路径行为不变。</li><li>macOS 宿主测试要点：bwrap 参数序断言用 <code>\\x00</code> 精确连接（避免 <code>--tmpfs /etc</code> 假命中 <code>--tmpfs /</code>）；不存在路径规范化原样返回 vs 已存在路径解析 <code>/private</code> 前缀——直接 API 测试的基目录须先 canonical 化（Linux 上两者天然相同）；外层 <code>ShellQuote</code> 会转义内层脚本的单引号，断言到首个内层引号为止。</li></ul><p><strong>P5-s3 已落地（2026-10-10）</strong>：<code>proxy_http.go</code>（HTTP CONNECT 正向代理 + 明文 HTTP 转发）+ <code>proxy_socks.go</code>（SOCKS5 无鉴权）+ <code>parent_proxy.go</code>（ParentProxyResolver：显式配置/环境变量解析链 + NO_PROXY CIDR/后缀匹配）+ <code>sandbox.go</code> 接线（<code>WithFilterRequest</code>/<code>StartProxyServers</code>/<code>StopProxyServers</code>/<code>ParentProxyResolver</code>；Reset 关代理）。TLS 终止/mitm 上游本就无实现（<code>MitmProxyConfig.socketPath</code> 指向外部进程），Go 保持结构位。<code>_test/sandbox_test/proxy_test.go</code> 黑盒 14 用例 + race×2 全绿。移植期发现与偏差（代码注释均已注明）：</p><ul><li><strong>三处上游缺陷修正</strong>：Java <code>handleClient</code> finally 无条件关 client——异步 pipe 刚返回隧道即断（上游移植缺陷，代理实际不可用），Go <code>tunnel</code> 阻塞等双泵；Java BufferedReader 预读吞请求体（其注释自认 unreliable），Go 统一经同一 bufio.Reader；Java 父代理应答的预读字节在 pipe 时丢弃（早发数据丢失），Go <code>bufferedConn</code> 并回。</li><li><strong>有意增量</strong>：代理服务器 Java 由外部基础设施启动 + <code>setProxyPorts</code> 回填，Go 增 <code>Manager.StartProxyServers()</code> 便捷接线（端口仍可外部注入）；配置经 provider 每请求读取（兑现 <code>UpdateConfig</code> 网络面活切换的既有承诺）；Stop 显式断在飞连接（Java shutdownNow 只中断线程不关 socket）；直连分支 HttpURLConnection → net/http；SOCKS 父路由 <code>Socket(Proxy.Type.HTTP)</code> → 手工 <code>dialViaParent</code>（两代理共用）。</li><li><strong>忠实怪癖保留</strong>：父代理 CONNECT 无端口即失败（对照明文分支有 80/443 回填）；CONNECT 端口非数字静默断连；SOCKS cmd 字段忽略（BIND/UDP 当 CONNECT）；https 父代理走裸 TCP；chunked 请求体按原始字节（含分帧）搬运；SOCKS 直连拨号无超时；filterRequest panic → 拒（Java catch Exception）；逐跳头 = RFC 7230 固定集 ∪ Connection 点名集；响应头每名取首值。</li><li><strong>Go 版本勘误（本卡修正库内既有代码）</strong>：当前 Go 的 <code>net.ParseIP</code> 对点分十进制也返回 16 字节 v4 映射形——<code>len(addr)==16</code> 判家族恒真，令 <code>127.0.0.0/8</code> 前 8 位（全零）匹配一切 v4 主机、裸 IP 误配 /128 越界；NO_PROXY CIDR 家族改按字面量判（<code>parentAddrBytes</code>），v6/映射形走 16 字节、点分十进制收窄 4 字节。<code>isValidIPv6Literal</code> 补 RFC 4291 尾组点分十进制形（<code>::ffff:127.0.0.1</code> 此前被判非 IP，v4 映射回环恒直连失效）。</li></ul><p><strong>P5-s4 已落地（2026-10-10）</strong>：<code>wfp.go</code>（对标 <code>WindowsSandboxBackend.java</code> 955 行 + windows/ 六 DTO——srt-win.exe CLI 薄包装）+ <code>sandbox.go</code> 接线（<code>wrapWindows</code> 分发/<code>CheckDependencies</code> windows 并入/<code>hasNetworkRestriction</code> 三处内联收敛为 helper）+ <code>_test/sandbox_test/wfp_test.go</code> 黑盒 8 用例全平台可跑（假 srt-win 脚本回放）。移植期发现与偏差（代码注释均已注明）：</p><ul><li><strong>网络隔离本体在 srt-win.exe（Rust 助手，非本库产物）</strong>：本地甄别组 + 按组 SID 键控的机器级 WFP 过滤器 + exec 子命令（受限令牌：组翻 deny-only + 加固 job）。真执行前置：一次性 install（单自提权进程=一次 UAC）+ 注销重登（组 SID 进 TokenGroups）。本库只负责 CLI 编排与状态解析。</li><li><strong>Java 手写 indexOf 式 JSON 解析 → encoding/json</strong>（对良好形成的 srt-win 输出行为等价，畸形输入错误面更干净）；port_range 缺省/null/单元素宽容为 nil 的 Java 语义保留。</li><li><strong>两处上游缺陷修正</strong>：① <code>SandboxManager.checkWindowsDependencies</code> 计算了 sublayerGuid 却调用未传入的旧版重载（死变量——配了自定义 sublayer 时依赖检查会查错 sublayer），Go 的 <code>Manager.CheckDependencies</code> 传入配置值；② wrap 的组引用分支与 <code>groupRefArgs</code> 几乎重复且判空语义不同（只判 null 不判 empty），Go 统一到 <code>groupRefArgs</code> 单入口。</li><li><strong>runSrtWin 死锁规避</strong>：Java 先读尽 stdout 再读 stderr——stderr 管道写满时互锁；Go exec 两侧并发缓冲。15 秒超时强杀 exit=-1（Java destroyForcibly 同款）。</li><li><strong>有意适配</strong>：安装指引文案去掉 <code>npx sandbox-runtime windows-install</code> 行（Node 生态专属），API 提示改 Go 名；<code>ErrWindowsBackendPending</code> 占位哨兵随卡删除（其文档声明的生命周期即「P5-s4 落地」）。</li><li>Windows 后端纯字符串/进程操作全平台编译全平台可测（<code>wfp.go</code> 中性文件名，三平台交叉构建门禁绿）；真 WFP 执行只在 windows 有意义，Manager 的 windows 分发分支在其余平台仅编译验证。</li></ul><h3 id="p6-按需解锁项全量落地-2026-10-11-立项并当日收口-对应前述对比表「部分-按需」清单" tabindex="-1">P6 按需解锁项全量落地（2026-10-11 立项并当日收口；对应前述对比表「部分/按需」清单） <a class="header-anchor" href="#p6-按需解锁项全量落地-2026-10-11-立项并当日收口-对应前述对比表「部分-按需」清单" aria-label="Permalink to &quot;P6 按需解锁项全量落地（2026-10-11 立项并当日收口；对应前述对比表「部分/按需」清单）&quot;">​</a></h3><blockquote><p>本节覆盖 2026-10-11 用户解锁的全部「部分/按需」项：team 协议 5/8 → 8/8、ragloader 4/7 重格式 → 7/7、ragrepo 12/14 → 14/14、talents 13/18 → 18/18、web crawler、agui agent 流映射、loop 集成桥、harness 压缩拦截器。九提交全绿。</p></blockquote><ul><li><strong>team 五协议（8/8）</strong>：A2A（点对点接力：<code>__transfer_to__</code> 工具 + handover 快车道 + 5 次熔断 + 模态检查 + 失败回退上一位专家）；ContractNet（合同网招投标：<code>__call_for_bids__</code>/<code>__submit_proposal__</code> + bidding 算法自动投标（role 词边界 +10 / capabilities 保底 60 加成 15 / 上限 95）+ 双层守卫（resolve 四段 + OnSupervisorRouting 旁路封堵）+ 中标执行门禁 + 轮次上限 2）；Blackboard（黑板：<code>__sync_to_blackboard__</code> 四可选参数 + 共享 KV + 保序 todo 队列（completed 精确删/result 命中联动/merge 结构化）+ FINISH 硬门禁（todo 未清或 FAILED）+ FAILED 回派）；MarketBased（市场：EMA 结算（0.6/0.4）+ 动态定价（base×(0.5+Q)×ln1p×多模态 1.5）+ ROI King/Budget Pick 看板）；None（透明容器：BuildGraph 留空，编排交 graphAdjuster）。</li><li><strong>ragloader 重格式（7/7）</strong>：docx/xlsx/pptx/pdf 四件经 <code>github.com/conductor-oss/markitdown</code> 统一引擎（用户指示替换自解实现；pdfium WASM 由 wazero 纯 Go 运行——零外部二进制）：pptx 以引擎页标记 <code>&lt;!-- Slide number: N --&gt;</code> 真页切分、xlsx 以 <code>## SheetName</code> 标题按 sheet 切分（DocumentMaxRows 语义映射为每文档最大非空行数、JSON 行映射形态随统一处理取消——输出 Markdown 表）、docx 按空行分段（PARAGRAPH）/整档（SINGLE）、pdf 页边界引擎不暴露——PAGE 退化为段块切分（page 元数据为块序近似页序，代码注明）；.doc/.ppt 旧格式显式拒绝维持（防 markitdown 纯文本兜底乱码）；markdown/html/ddl 三件自解实现不变。</li><li><strong>ragrepo 12 后端（14/14）</strong>：REST 基座（RESTClient/RestRepositoryBase/ClampScore）；chroma（v1/v2 heartbeat 自适应、双层列表响应、where 字典）；dashvector（一套 REST 覆盖 dashvector + dashvector-official 两模块——官方 SDK 即该 REST 的封装）；sqlrepo（mysql：JSON embedding + COSINE_SIMILARITY 纯 SQL 存储函数——Java 全表扫描原语义；mariadb：VECTOR 列 + VEC_DISTANCE_EUCLIDEAN 服务端排序 + 客户端余弦重算）；redisrepo（RediSearch FT.CREATE ON JSON VECTOR HNSW + FT.SEARCH KNN Dialect2 小端 BLOB + JSON.SET pipeline，go-redis 与 cache 插件同客户端；drop 不 FLUSHDB）；vectorest（opensearch knn_vector + 内联 filter / weaviate GraphQL nearVector + certainty + where 枚举不加引号 / tcvectordb 唯一服务端 embedding——save 不嵌入检索传原文 / vectorex basic auth + 余弦 clamp）。</li><li><strong>talents 13/18 → 18/18</strong>：零依赖批七件——generation（ImageDriver/VideoDriver SPI + generate.Model 适配 + 文件名消毒/去重/沙箱）、social（钉钉签名在 URL / 飞书签名在 body / 企微无签名——HmacSHA256(ts+&quot;\\n&quot;+secret, secret) 双位置）、mail（net/smtp + MIME 混合附件 + HTML 探测）、mount（Mount/MountSource/MountManager/SkillCatalog/AgentCatalog——@alias 逻辑路径 + SKILL.md/AGENT.md 限深扫描）、memory（md 原子写 + CJK bi-gram 分词 + idf² 两段评分 + TTL 分档 + scope 覆盖序 + 五工具含 consolidate 读回校验）、code（LanguageProvider SPI 六内置 + CODE.md 规约生成）、data（KVStore SPI + ai:memory: 键 + 30 天 TTL）；依赖批四件——gateway（OpenAPI V3+V2 解析：参数四桶/$ref 展开/PathItem 级合并/multipart/outputSchema + call_api 运行时 + 四档位）、pdf（parse 复用 ragloader + create 声明式降级 .html 载体——Go 无 openhtmltopdf）、cli（bash 同步 + bash_start/wait/stop 异步会话 + 进程树终止 + 快照形态）、lsp（Content-Length 帧层 jsonrpc over stdio 自实现 + initialize/didOpen/publishDiagnostics + 14 内置服务器命令面）。不迁维持两项：lucene（ES/内存覆盖）、聚合包。</li><li><strong>web crawler</strong>：JINA（r.jina.ai/{url} + X-Return-Format markdown）与 Firecrawl（/v1/scrape + onlyMainContent）双驱动 + crawl_url 工具。</li><li><strong>agui agent 流映射</strong>：AgentEventAdapter 最小能力接口（Java 反射的 Go 对应物）+ 六分支分派（SupervisorDelta 恒 CUSTOM、ChatEvent 委托复用状态机、工具三件、终态只记、其余 CUSTOM）；ai/agent/aguiadapt.go 适配器（Meta 键 callId/toolName 与 react 真实事件对齐）。</li><li><strong>loop 集成桥</strong>：AgentIntegration（Ralph/UltraQA/agent 驱动三启动 + ExecutionStatus）、FlowIntegration（变量提取/回写/flowId 状态）、HarnessIntegration（HarnessCaller 最小接口解耦 + 工具驱动/harness 驱动两形态）。</li><li><strong>harness 压缩拦截器</strong>：OnReasonStart 非强制触发（消息数/token 阈值）+ OnReasonRetry PTL 九关键词强制（forceLevel 递减预算）；固定前缀/双维度截断/原子对对齐/语义锚定/策略摘要+兜底/悬空清理/工作记忆重建全链；KeyInfo（四维脱水）+ Hierarchical（滚动摘要 trace attr 持久 + PTL 二分降级）+ Composite 缺省装配（100/0.75）；近似 token 计数器（jtokkit 的零依赖保守替代，WithTokenCounter 可注入）。</li></ul><p><strong>验收（全绿）</strong>：全量 27 测试模块 + 库模块编译检查零失败；黄金样本覆盖（协议场景/过滤翻译七族/OpenAPI 解析/HMAC/PDF/快照）；race 抽查绿；CLAUDE.md/go.work 同步；零真实外网依赖（httptest 回放/sqlite/真 sh -c 执行器）。</p><h3 id="p7-用户指示修正-2026-10-11" tabindex="-1">P7 用户指示修正（2026-10-11） <a class="header-anchor" href="#p7-用户指示修正-2026-10-11" aria-label="Permalink to &quot;P7 用户指示修正（2026-10-11）&quot;">​</a></h3><ul><li><strong>重格式统一处理</strong>：docx/xlsx/pptx/pdf 四件弃自解实现，统一经 <code>github.com/conductor-oss/markitdown</code>（pdfium WASM 由 wazero 纯 Go 运行——零外部二进制）；pptx 真页标记切分、xlsx sheet 切分、docx 空行分段、pdf 段块近似页切分（页边界引擎不暴露）；<code>.doc</code>/<code>.ppt</code> 旧格式显式拒绝维持。测试夹具升级为 markitdown testdata 真实文件（Apache-2.0 注明）。</li><li><strong>bleve talent（Java lucene 的 Go 对应物，用户指示解禁并更名）</strong>（覆盖原 06 §2「不迁」决策）：不用 Elasticsearch（需部署服务非等价替代）也不用 gojieba（cgo 绑定无纯 Go 版本）——<strong>Bleve</strong>（blevesearch/bleve/v2，内存索引 + BM25——Lucene 的 Go 等价物）+ <strong>gse</strong>（go-ego/gse，纯 Go 中文分词、jieba 词典系、内嵌词典）。落 <code>plugins/ai/talent/bleve</code>：full_text_search/refresh_search_index 双工具语义逐字对标 Java（忽略名/后缀白名单可配、检索自动建索引、得分/行号/预览格式化）；gse CutSearch（搜索引擎模式 + HMM）注册为 Bleve 自定义 analyzer、索引与查询同源分词；特殊字符免转义（MatchQuery 走分析器非查询语法）。测试搬译 Java LuceneTalentTest 六用例 + 中文分词专项。</li><li><strong>ragloader 重格式夹具</strong>：markitdown testdata 真实四件（test.docx/xlsx/pptx/pdf）。</li></ul><h3 id="p5-m-模型补全与其余方言扩展-2026-10-10-立项并落地-契约-02-chat-core-md-§11-与-§2-1-5-23" tabindex="-1">P5-M 模型补全与其余方言扩展（2026-10-10 立项并落地；契约 <code>02-chat-core.md</code> §11 与 §2.1 #5/#23） <a class="header-anchor" href="#p5-m-模型补全与其余方言扩展-2026-10-10-立项并落地-契约-02-chat-core-md-§11-与-§2-1-5-23" aria-label="Permalink to &quot;P5-M 模型补全与其余方言扩展（2026-10-10 立项并落地；契约 `02-chat-core.md` §11 与 §2.1 #5/#23）&quot;">​</a></h3><ul><li><strong>ai/rerank</strong>（02 §11 &quot;rerank P4（RepositoryTool 依赖）&quot; 的补欠）：Model/Builder/RequestDesc + openai/dashscope 两方言；<code>Rerank</code> 写回 score 后降序返回，满足 P4-b 预留的 <code>rag.Reranker</code> 接口位；条数不等显式报错（Java 直接越界的收敛）。usage 不进 Go 契约（与 embedding 对齐）。</li><li><strong>ai/generate</strong>（02 §11 &quot;generate P5&quot;）：Config 带 TaskURL（裸拼接语义，<code>TaskURLAndId</code> 不走 path.Join）+ openai/ollama/dashscope 三方言；Content{Text,Data,URL,MimeType} + Value 优先级 url&gt;data&gt;text；模型级默认选项配置形态字符串强类型转换（对标 GenerateOptions.putAll：bool/整数/浮点）。忠实怪癖：dashscope task_id 分支无 taskUrl 守卫（空 taskUrl 时 url=裸拼接结果，对照 openai 有双非空守卫）、ollama error 键存在即错、ollama matched 恒 false 仅兜底。</li><li><strong>ai/ui/agui</strong>（06 §6.2）：31 事件型（含 5 个 Deprecated THINKING_*）+ Wrapper 事件映射状态机。忠实语义：TEXT_START 落 default 分支降级 CUSTOM(&quot;text_start&quot;)（正文开界由 TEXT_DELTA 懒开）、ABORT/ERROR terminal 后 finish 静默、SSE 帧无 [DONE] 终标（与 aisdk 的协议差异）。agent 事件流映射（Java toAgUiAgentStream 的反射版）不在首卡——依赖 ai/agent 事件型，后续需要前端协议时补。</li><li><strong>ai/dialect/gemini Interactions API</strong>（00 §2.1 #5 &quot;gemini(+interactions)&quot;）：<code>InteractionsDialect</code>（google-interactions）+ URL 归一矩阵 + input[] step 数组请求 + event_type 帧协议解析（step 累积器挂 StreamContext attrs 并发隔离、服务端工具三态、搜索结果逐项投影去重、step.stop 签名绑定、TOOL_CALL_END 由 core 收尾）+ 非流式 steps[] 终态与六终态映射 + usage（prompt=input+tool_use、webSearch=Σsearch 类 grounding 计数）。</li><li><strong>MCP×Talent 桥</strong>（06 §8）：<code>aimcp.NewTalent</code>（远端 talent://metadataMcp 元数据 + 四 hide 管理工具跨进程回环）+ <code>RegisterTalent</code>（本地 talent 导出）。Go 的 Talent 接口无 error 位：IsSupported fail-closed、Instruction/Tools 空值回退、OnAttach 记日志。</li></ul><p><strong>P5-M 已落地（2026-10-10，四提交 06772ea/c2b5f8b/ee619a9）</strong>：黄金样本搬译 Java 两 rerank 测试、三 generate 测试、AgUiStreamWrapperTest 七用例、interactions 五测试文件；httptest 端到端（rerank 回环、generate 强类型转换、agui 假 OpenAI、interactions alt=sse）。</p><h3 id="p5-r-ragloader-三件-2026-10-10-立项并落地-契约-05-rag-design-md-§7" tabindex="-1">P5-R ragloader 三件（2026-10-10 立项并落地；契约 <code>05-rag-design.md</code> §7） <a class="header-anchor" href="#p5-r-ragloader-三件-2026-10-10-立项并落地-契约-05-rag-design-md-§7" aria-label="Permalink to &quot;P5-R ragloader 三件（2026-10-10 立项并落地；契约 `05-rag-design.md` §7）&quot;">​</a></h3><p>落位 <code>plugins/ai/ragloader</code>（goldmark + goquery + db）：<strong>MarkdownLoader</strong>（Heading 恒切分 + 水平线/代码块/块引用可选切分——块引用切的是块首不切块尾、代码块后恒切分的 commonmark SplitVisitor 语义逐分支对标；标题上 metadata category=header_N+title、行内码/围栏码染色、软硬换行与列表项归一空格）；<strong>HtmlSimpleLoader</strong>（goquery body 归一化正文 + title/description/language 元数据）；<strong>DdlLoader</strong>（SQL 模板全参数化、缺省 MySQL information_schema 形态、<code>#{key}</code> 占位符替换、完整 DDL 重组截断保留表体；Java 源码 shcema 笔误在 Go 修正）。pdf/word/excel/ppt 维持 00 §2.2-I 的分批降级决策（解析库按格式独立立项）。测试入 <code>_test/ai_plugin_test</code>（markdown 切分矩阵、html 元数据、ddl sqlite 回环三形态）。</p><h3 id="p5-v-ragrepo-样板后端-2026-10-10-立项并落地-契约-05-rag-design-md-§6" tabindex="-1">P5-V ragrepo 样板后端（2026-10-10 立项并落地；契约 <code>05-rag-design.md</code> §6） <a class="header-anchor" href="#p5-v-ragrepo-样板后端-2026-10-10-立项并落地-契约-05-rag-design-md-§6" aria-label="Permalink to &quot;P5-V ragrepo 样板后端（2026-10-10 立项并落地；契约 `05-rag-design.md` §6）&quot;">​</a></h3><p>落位 <code>plugins/ai/ragrepo</code>：共享 <strong>过滤表达式解析器</strong>（enjoy 判定子集：==/!=/超小于等于/&amp;&amp;/||/!/裸字段/裸布尔/括号/单双引号/裸数值 → 节点树 → ES bool query 与 SQL WHERE 双翻译；方法调用等不可译形态 ok=false 回退 rag.Refilter 内存过滤；SQL 值一律参数化——Java pgvector FilterTransformer 内联字符串的注入面收口）。<strong>es.Repository</strong>（复用 plugins/elasticsearch Client）：检索按 ES8 现代语义重写——VECTOR 走顶层 knn（Java 把 knn 子句误包进 bool.must）、EXACT_KNN script_score、HYBRID 恒 bool should [match+script_score]；批量写入 metadata 平铺 + 分批进度。<strong>pgvector.Repository</strong>（database/sql）：VECTOR(dims)+JSONB+元数据列建表、ivfflat cosine 索引、upsert ON CONFLICT、1−(embedding&lt;=&gt;vec) 相似度 + 过滤 WHERE（声明列直引、其余 metadata-&gt;&gt;&#39;k&#39;）+ 占位符随过滤参数偏移。测试面（05 §9.5）：SQL 骨架经导出的 Build* 函数黄金断言 + stubESClient 全链路；真连开关 RAG_PGVECTOR_DSN 留位（FLOW_MYSQL_DSN 先例）。其余后端（milvus/qdrant/redis…）维持 00 §2.1 #22 的按需逐个决策。</p><h3 id="p5-h-harness-编排容器-2026-10-10-立项并落地-契约-06-talents-and-extended-md-§4" tabindex="-1">P5-H harness 编排容器（2026-10-10 立项并落地；契约 <code>06-talents-and-extended.md</code> §4） <a class="header-anchor" href="#p5-h-harness-编排容器-2026-10-10-立项并落地-契约-06-talents-and-extended-md-§4" aria-label="Permalink to &quot;P5-H harness 编排容器（2026-10-10 立项并落地；契约 `06-talents-and-extended.md` §4）&quot;">​</a></h3><p>落位 <code>ai/harness</code> 新模块（依赖 ai/agent + flow + yaml.v3）：<strong>AgentDefinition</strong>（frontmatter 全字段 + 序列化往返 + 五内置 markdown 代理 embed：explore/general/plan/bash/git-summary——hidden 与无写权限语义照搬）；<strong>PermissionEngine</strong>（priority 降序 + 同序 DENY&gt;ALLOW&gt;ASK + 首条匹配 + glob→正则）与 <strong>HITL 三策略</strong>（Bash 六规则/Write 路径回溯与敏感文件/Web 高风险域名）+ PermissionInterceptor（<code>ai.Interceptor.InterceptTool</code> 缝否决——为此给 <code>ai.ToolRequest</code> 增量补 Name 位；ASK 经审批回调放行并记忆 allow 规则）；<strong>BashCommandClassifier</strong>（只读白名单含 git 子命令细分、sed -i/重定向/git branch -d 排除、&amp;&amp;/||/; 分段）；<strong>CommandRegistry + MarkdownCommand</strong>（Claude Code 自定义命令兼容：$1..N/$ARGUMENTS 模板、子目录冒号命名）；<strong>AgentManager</strong>（注册表 + 目录回源 + hidden 过滤）与 <strong>AgentFactory</strong>（definition → react.Builder）；<strong>TaskTalent/GenerateTalent</strong>（task 串行与 multitask 并行 XML 聚合、generate 复制 general 覆写 + .soloncode 持久化）；<strong>Engine</strong>（模型注册表/工具池/主代理懒加载热重建/扩展 initialize 生命周期/Prompt 入口）。</p><p>域收窄（06 §2 优先级矩阵的 talents 只有五件落地）：工具名映射按 Go 已有 talent 工具集（*/**/pi 展开收窄为 read/write/shell/webfetch 等 + clock 收尾）；terminal/code/memory/skill/lsp 族 talent 未迁移——经 <code>Engine.SetToolMapper</code> 缝对接，随后续 talents 解锁补齐。上下文压缩拦截器（Java ContextCompressionInterceptor）同理留缝。</p><h3 id="p5-l-loop-持久循环引擎-2026-10-10-立项并落地-契约-06-talents-and-extended-md-§5" tabindex="-1">P5-L loop 持久循环引擎（2026-10-10 立项并落地；契约 <code>06-talents-and-extended.md</code> §5） <a class="header-anchor" href="#p5-l-loop-持久循环引擎-2026-10-10-立项并落地-契约-06-talents-and-extended-md-§5" aria-label="Permalink to &quot;P5-L loop 持久循环引擎（2026-10-10 立项并落地；契约 `06-talents-and-extended.md` §5）&quot;">​</a></h3><p>落位 <code>ai/loop</code> 新模块（依赖 ai + flow 单点）：<strong>状态机</strong>（IDLE→PLANNING→EXECUTING→VERIFYING→FIXING→COMPLETED/FAILED(+PAUSED) 转移表）+ 引擎主循环（迭代 → VERIFYING → 验证裁决：passed→续跑/COMPLETED、needsFix→FIXING 修复轮、否则 FAILED）；<strong>Strategy SPI</strong> 三内置：<strong>Ralph</strong>（PRD 文档/用户故事/完成度统计 + Architect→VerificationState→Critic 双层验证与上限强判 + 实现即完成声明语义）、<strong>TeamPipeline</strong>（PLAN→PRD→EXEC→VERIFY→FIX 全程 contextData 驱动、非法转移守卫、取消/保留恢复、fix 溢出 FAILED）、<strong>UltraQA</strong>（质量门禁 + CommandExecutor 缝 + 同失败三连指纹归一 + 轮次上限；ProcessCommandExecutor 走 sh -c/cmd /c）；<strong>磁盘状态</strong>（.loops/{state/{ralph,team,ultraqa,sessions},prd,progress} 布局、_meta 信封 + data 双层 JSON 旧格式兼容、原子写 tmp+rename 无残留）；<strong>互斥守卫</strong>（内存 activeModes + 磁盘同会话双检）；<strong>Autopilot</strong>（五阶段管道 + 适配器 SPI + 跟踪摘要 + 取消）。</p><p>Java 两处已知缺陷的 Go 修正（模块文档注明）：① iterationCount 每轮真实递增（保险丝真实生效——Java 恒 0 只对 MaxIterations=0 有效）；② pause 以条件变量阻塞执行 goroutine（resume 真续跑——Java pause 使线程退出、恢复不续跑）。stop→FAILED 的 Java 语义保留。agent/flow/harness 三集成桥（Java integration 包的反射版）不随首卡——loop 的 Strategy/StoryImplementor 已是函数位，宿主直接注入即可。</p><hr><h2 id="_9-全局验收清单-definition-of-done" tabindex="-1">9. 全局验收清单（Definition of Done） <a class="header-anchor" href="#_9-全局验收清单-definition-of-done" aria-label="Permalink to &quot;9. 全局验收清单（Definition of Done）&quot;">​</a></h2><ul><li>[x] <code>go test</code>（显式模块路径列表）全绿（P0–P5 全量：27 测试模块 + 库模块编译检查）；被测模块全部零真实外网依赖（httptest 假服务回放/嵌入式 sqlite/真 sandbox-exec 平台内建）。</li><li>[x] 流式 6 不变量、copy-before-mutate、MCP 判别/协商矩阵有命名测试固化（<code>_test/ai_test/stream_test.go</code>、<code>_test/ai_agent_test/team_test.go</code>、<code>_test/mcp_test/{mcp,client}_test.go</code>）。</li><li>[x] 方言请求 JSON 与关键 SSE 回放用例有黄金样本（来源标注 Java 测试文件：rerank/generate/agui/interactions 各测试文件头注明搬译来源；P0–P4 既有黄金沿用）。</li><li>[x] <code>go.work</code> / CLAUDE.md（模块表 + 测试表）/ <code>docs/arch/index.md</code> / VitePress sidebar 同步更新（P5 收口一并完成；index/sidebar 自 P3 起收录八篇未再变）。</li><li>[x] 每个 P 期一次多模块标签发布演练（<code>ai/v1.0.3</code>、<code>mcp/v1.0.3</code>、<code>ai/agent/v1.0.3</code>、<code>ai/flow/v1.0.3</code>、<code>plugins/ai/v1.0.3</code>；P5 新模块 <code>sandbox/v1.0.3</code>、<code>ai/harness/v1.0.3</code>、<code>ai/loop/v1.0.3</code>、<code>plugins/ai/ragloader/v1.0.3</code>、<code>plugins/ai/ragrepo/v1.0.3</code> 随本期补打）。</li><li>[x] API 命名走查：无 <code>Get</code> 冗余前缀访问器（P5 新模块 grep 复核零命中）、泛型受限处走包级 helper（与 01 §7 速查一致）。</li></ul><h2 id="_10-风险与对策-tdd-视角" tabindex="-1">10. 风险与对策（TDD 视角） <a class="header-anchor" href="#_10-风险与对策-tdd-视角" aria-label="Permalink to &quot;10. 风险与对策（TDD 视角）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>对策</th></tr></thead><tbody><tr><td>方言语义漂移（尤其 snapshot delta 归一）</td><td>黄金样本 + 回放测试先行；Java 侧行为差异记录在案（issue 式）</td></tr><tr><td>流式取消边界（SSE 半帧/工具执行中）</td><td>ctx 注入点表（01 §3）逐点测试；假延迟注入覆盖竞态</td></tr><tr><td>flow 增量（D8，已定稿 A）引入回归</td><td>单独提交 + flow 全量回归；备选方案 B 留档可切（契约不变）</td></tr><tr><td>MCP 规范理解偏差</td><td>协议常量/错误码与 spec 章节对照注释；互操作冒烟（标准客户端/服务端脚本）</td></tr><tr><td>范围蔓延（P5 长尾）</td><td>P5 项一律独立立项 + 触发条件；主线 DoD 不含 P5</td></tr><tr><td>Go 解析生态缺口（pdf/ppt）</td><td>能力声明式降级（返回明确不支持错误）+ 独立插件包隔离依赖</td></tr></tbody></table><h2 id="_11-提交粒度建议" tabindex="-1">11. 提交粒度建议 <a class="header-anchor" href="#_11-提交粒度建议" aria-label="Permalink to &quot;11. 提交粒度建议&quot;">​</a></h2><ul><li>一个 P-x 小节 ≈ 3–8 个提交；每提交「实现 + 对应测试 + 文档同步」三件套。</li><li>消息前缀按模块：<code>ai:</code>、<code>mcp:</code>、<code>ai/agent:</code>、<code>ai/flow:</code>、<code>plugins/ai:</code>、<code>flow:</code>（D8 增量单独成提交）。</li><li>黄金样本与回放夹具独立提交（便于 review 数据与逻辑分离）。</li><li>每期收口一个 <code>docs/arch/ai/</code> 状态注记（在 00 顶部加一行「P-x 已落地」式记录，对照 flow 系列落地后的记忆惯例）。</li></ul><h2 id="_12-起步-p0-a-第一张卡示例" tabindex="-1">12. 起步（P0-a 第一张卡示例） <a class="header-anchor" href="#_12-起步-p0-a-第一张卡示例" aria-label="Permalink to &quot;12. 起步（P0-a 第一张卡示例）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>卡：ai/P0-a 消息与内容块</span></span>\n<span class="line"><span>1. go work edit -use ./ai ./_test/ai_test（先建两模块骨架 go.mod，依 00 §4.3 模板）</span></span>\n<span class="line"><span>2. _test/ai_test 先写失败测试：</span></span>\n<span class="line"><span>   TestMessageRoundtrip（四角色 + 多模态块 type 判别往返）</span></span>\n<span class="line"><span>   TestOfUserAugment / TestMessageCloneDeep / TestBase64Downgrade</span></span>\n<span class="line"><span>3. 实现 ai/message.go + ai/content.go 至全绿</span></span>\n<span class="line"><span>4. CLAUDE.md 模块表 + 测试表登记；提交 `ai: 消息与内容块（P0-a）`</span></span></code></pre></div>',111)])])}const u=o(r,[["render",i]]);export{h as __pageData,u as default};
